import { Signal } from './signal';
import { midiVelocityToNoteVelGain, toFrequency } from './helpers';
import { Msynth } from './msynth-worklet';
import VoiceState from './VoiceState';
import { SynthWorkletRole } from './types';

/** Replace NaN/Infinity with 0 so bad signal math never silences or corrupts the output. */
function sanitizeSample(x: number): number {
  return Number.isFinite(x) ? x : 0;
}

const SILENCE_THRESHOLD = 0.0001;

export class Synth {
  noteNums: number[] = [];

  constructor(
    private readonly msynth: Msynth,
    readonly channel: number,
    readonly outs: Signal[],
    readonly allSignals: Signal[],
    readonly voiceState: VoiceState,
    readonly role: SynthWorkletRole
  ) {}

  /** Raw state array; kept so built-in signals / compiled patches can index params by number. */
  get params() {
    return this.voiceState._state;
  }

  /** Shared params array (one copy per synth, shared by all voices + effect). */
  get sharedParams() {
    return this.voiceState._sharedParams;
  }

  get numSamples() {
    return this.msynth.numSamples;
  }

  get samples() {
    return this.msynth.samples;
  }

  // Note state lives in the shared voice state so the UI can read it too.
  get noteNum() {
    return this.voiceState.midiNote;
  }

  set noteNum(value: number) {
    this.voiceState.midiNote = value;
  }

  /** Base note frequency; glide is applied on top of this. */
  get noteFreq0() {
    return this.voiceState.noteFreq0;
  }

  set noteFreq0(value: number) {
    this.voiceState.noteFreq0 = value;
  }

  get noteVel() {
    return this.voiceState.velocity;
  }

  set noteVel(value: number) {
    this.voiceState.velocity = value;
  }

  processMidiMessage([d1, d2, d3]: Uint8Array) {
    const channel = d1 & 0b1111;
    if (channel !== this.channel) {
      return; // this message is not for me, so ignore it
    }

    switch (d1 >> 4) {
      case 0b1001: {
        const note = d2;
        const velocity = d3;
        if (velocity === 0) {
          // some devices send noteOn with vel 0 for noteOff!
          this.noteOff(note, velocity);
        } else {
          this.noteOn(note, velocity);
        }
        break;
      }
      case 0b1000: {
        const note = d2;
        const velocity = d3;
        this.noteOff(note, velocity);
        break;
      }
    }
  }

  noteOn(note: number, vel: number) {
    this.noteNums.push(note);
    this.noteNum = note;
    this.noteFreq0 = toFrequency(note);
    this.noteVel = midiVelocityToNoteVelGain(vel);
    this.allSignals.forEach(s => s.noteOn?.(this, false));
    this.voiceState.replenishSilenceCountdown();
  }

  noteOff(note: number, vel: number) {
    const idx = this.noteNums.indexOf(note);
    if (idx < 0) {
      return;
    }
    const retriggerNext = idx === this.noteNums.length - 1;
    this.noteNums.splice(idx, 1);
    const nextNote = this.noteNums.at(-1);
    if (nextNote != null && retriggerNext) {
      this.noteNum = nextNote;
      this.noteFreq0 = toFrequency(nextNote);
      this.allSignals.forEach(s => s.noteOn?.(this, true));
    } else if (this.noteNums.length === 0) {
      this.allSignals.forEach(s => s.noteOff?.());
    }
  }

  addSamplerState(phase: number, _in: number, out: number, loopIn: number, loopOut: number) {
    this.voiceState.addSamplerState(phase, _in, out, loopIn, loopOut);
  }

  /** Add this synth's (voice's) contributions to the output. */
  processFrame(inputs: Float32Array[][], output: Float32Array[], frameIdx: number) {
    if (this.role !== 'effects' && this.voiceState.isFree) {
      // When the sampler tool is open, keep voice 0 evaluating its signals so the UI can show the
      // computed in/out/loop points without any notes playing. We don't touch the output or the
      // silence countdown, so the voice stays free/allocatable and produces no sound.
      if (this.msynth.previewSampler && this.role === 'voice' && this.channel === 0) {
        this.voiceState.clearSamplerStates();
        this.allSignals.forEach(s => s.computeSample(frameIdx, this, inputs));
      }
      return;
    }

    this.voiceState.clearSamplerStates();
    this.allSignals.forEach(s => s.computeSample(frameIdx, this, inputs));
    const gain = this.voiceState.gain;
    let audible = false;
    if (this.outs.length === 2 && output.length >= 2) {
      // stereo
      for (let ch = 0; ch < 2; ch++) {
        const sample = sanitizeSample(this.outs[ch].value * gain);
        output[ch][frameIdx] += sample;
        if (Math.abs(sample) >= SILENCE_THRESHOLD) {
          audible = true;
        }
      }
    } else {
      // mono
      const sample = sanitizeSample(this.outs[0].value * gain);
      for (let ch = 0; ch < output.length; ch++) {
        output[ch][frameIdx] += sample;
      }
      if (Math.abs(sample) >= SILENCE_THRESHOLD) {
        audible = true;
      }
    }

    // Keep the glided note frequency current so the UI can read it.
    this.voiceState.noteFreq = this.voiceState.noteFreq0 * Math.pow(2, this.voiceState.glide / 12);

    if (this.role !== 'effects') {
      if (audible) {
        this.voiceState.replenishSilenceCountdown();
      } else {
        this.voiceState.decrementSilenceCountdown();
      }
    }
  }
}
