import { Signal, scalar } from './signal';
import { Module } from './module';
import { MIDDLE_C_FREQ, SAMPLE_RATE, SAMPLE_RATE_RECIP, SP_TEMPO, TAU } from './constants';
import * as env from './env';
import * as glide from './glide';
import * as effects from './effects';
import { ladder } from './ladder';
import { clamp, interpolatedRead } from './helpers';
import { Synth } from './synth';

export const msynthLib: Record<string, Module<any>> = {
  // ----- oscillators -----

  sine: Module.make({ input: () => scalar(440) }, params => {
    const f = params.input;
    let phase = 0;
    return Signal.new(() => {
      const sample = Math.sin(phase * TAU);
      const phaseInc = f.value * SAMPLE_RATE_RECIP;
      phase += phaseInc;
      phase -= Math.floor(phase);
      return sample;
    });
  }),

  saw: Module.make({ input: () => scalar(440) }, params => {
    const f = params.input;
    let phase = 0;
    return Signal.new(() => {
      const naiveSample = 2 * phase - 1;
      const phaseInc = f.value * SAMPLE_RATE_RECIP;
      const sample = naiveSample - polyBlep(phase, phaseInc);
      phase += phaseInc;
      phase -= Math.floor(phase);
      return sample;
    });
  }),

  tri: Module.make({ input: () => scalar(440) }, params => {
    const f = params.input;
    let phase = 0;
    let integrator = 0;
    return Signal.new(() => {
      const phaseInc = f.value * SAMPLE_RATE_RECIP;
      const square =
        (phase >= 0.25 && phase < 0.75 ? -1.0 : 1.0) -
        polyBlep((phase + 0.75) % 1, phaseInc) +
        polyBlep((phase + 0.25) % 1, phaseInc);
      integrator = 0.999 * integrator + square * phaseInc * 4;
      phase += phaseInc;
      phase -= Math.floor(phase);
      return integrator;
    });
  }),

  pulse: Module.make(
    { input: () => scalar(440), w: () => scalar(0.5), sync: () => scalar(0) },
    params => {
      const { input: f, w, sync } = params;
      let phase = 0;
      let prevSyncValue = 0;
      return Signal.new(() => {
        const naiveSample = phase < w.value ? -1 : 1;
        const phaseInc = f.value * SAMPLE_RATE_RECIP;
        const sample =
          naiveSample - polyBlep(phase, phaseInc) + polyBlep((phase - w.value + 1) % 1, phaseInc);

        let syncDetected = false;
        if (prevSyncValue < 0 && sync.value >= 0) {
          // estimate zero crossing between previous and current value
          // prev + (curr - prev) * r = 0  =>  r = -prev / (curr - prev)
          const r = -prevSyncValue / (sync.value - prevSyncValue);
          // time since crossing to current sample = (1 - r) * dt
          phase = Math.floor((1 - r) * phaseInc);
          syncDetected = true;
        }
        prevSyncValue = sync.value;

        if (!syncDetected) {
          phase += phaseInc;
          phase -= Math.floor(phase);
        }
        return sample;
      });
    }
  ),

  sampler: Module.make(
    {
      input: () => scalar(0),
      in: () => scalar(0),
      out: () => scalar(1),
      loopIn: () => scalar(0),
      loopOut: () => scalar(1),
    },
    params => {
      const { input: f, in: __in, out: _out, loopIn: _loopIn, loopOut: _loopOut } = params;
      let phase = 0;
      let stage: 'off' | 'on' | 'on-loop' = 'off';
      let sustain = false;

      function crossed(threshold: number, oldValue: number, newValue: number, direction: 1 | -1) {
        if (direction === 1) {
          return oldValue < threshold && threshold <= newValue;
        } else {
          return newValue < threshold && threshold <= oldValue;
        }
      }

      return Signal.new({
        nextSample(synth) {
          if (
            synth.numSamples === 0 || // samples haven't loaded yet
            stage === 'off'
          ) {
            phase = -1;
            return 0;
          }

          const _in = clamp(__in.value, 0, 1);
          const out = clamp(_out.value, 0, 1);
          const loopIn = clamp(_loopIn.value, 0, 1);
          const loopOut = clamp(_loopOut.value, 0, 1);

          const dir = stage === 'on' ? (out >= _in ? 1 : -1) : loopOut >= loopIn ? 1 : -1;
          const loopingMakesSense = dir > 0 ? loopIn < loopOut : loopIn > loopOut;

          const sample = interpolatedRead(synth.samples, phase * synth.numSamples);
          const oldPhase = phase;
          phase = clamp(phase + dir * (f.value / MIDDLE_C_FREQ / synth.numSamples), 0, 1);
          if (crossed(out, oldPhase, phase, dir)) {
            // if we hit "out", we're done
            phase = -1;
            stage = 'off';
          } else if (sustain && loopingMakesSense && crossed(loopOut, oldPhase, phase, dir)) {
            // when we hit loopOut, we're looping (jump back to loopIn)
            phase = loopIn;
            stage = 'on-loop';
          }
          return sample;
        },

        initialValue: 0,

        noteOn() {
          stage = 'on';
          phase = __in.value;
          sustain = true;
        },

        noteOff() {
          sustain = false;
        },

        writeSharedState(synth: Synth) {
          synth.addSamplerState(phase, __in.value, _out.value, _loopIn.value, _loopOut.value);
        },
      });
    }
  ),

  // ----- glides -----

  // TODO: consider adding lag(s: Signal, t: Signal) -- lag processor

  /** glide linearly (t is time for the signal to move 1 unit) */
  lglide: Module.make({ input: () => scalar(0), t: () => scalar(0.1) }, params =>
    glide.linear(params.input, params.t)
  ),

  /** glide exponentially (t is time for the signal to move 1 octave, in seconds) */
  eglide: Module.make({ input: () => scalar(0), t: () => scalar(1) }, params =>
    glide.exponential(params.input, params.t, false)
  ),

  legato: Module.make({ input: () => scalar(0), t: () => scalar(1) }, params =>
    glide.exponential(params.input, params.t, true)
  ),

  // ----- envelopes -----

  // TODO: in the 2600, the vca has a linear/exponential switch.
  // look at that and think about it -- maybe there are better building blocks for us?

  // TODO: consider taking an input param, whose default value is 1
  // (this would enable ad, adsr, etc. to be used in a pipeline kind of way, w/o multiplying by the input)

  ad: Module.make({ input: () => scalar(1), a: () => scalar(0), d: () => scalar(0.2) }, params =>
    env.ad(params.input, params.a, params.d)
  ),

  adsr: Module.make(
    {
      input: () => scalar(1),
      a: () => scalar(0),
      d: () => scalar(0),
      s: () => scalar(1),
      r: () => scalar(0.2),
    },
    params => env.adsr(params.input, params.a, params.d, params.s, params.r)
  ),

  gate: Module.make({ input: () => scalar(1) }, params => env.gate(params.input)),

  env: Module.make(
    {
      input: () => scalar(0),
      attackTime: () => scalar(0.001),
      releaseTime: () => scalar(0.05),
      filterFreq: () => scalar(1000),
      threshold: () => scalar(0.05),
    },
    params => {
      const { input, attackTime, releaseTime, filterFreq, threshold: _threshold } = params;
      let currentEnvelope = 0;
      let prevInput = 0;
      return Signal.new(() => {
        const attackCoef = Math.exp(-1.0 / (SAMPLE_RATE * attackTime.value));
        const releaseCoef = Math.exp(-1.0 / (SAMPLE_RATE * releaseTime.value));
        const filterCoef = 1.0 / (SAMPLE_RATE * filterFreq.value + 1.0);
        const threshold = _threshold.value;

        // 1. Pre-filter (Low-pass)
        const filteredInput = prevInput + attackCoef * (input.value - prevInput);
        prevInput = filteredInput;

        // 2. Full-wave rectification
        let rectified = Math.abs(filteredInput);

        // 3. Apply Threshold -- if the signal is below the threshold, it's ignored
        if (rectified < threshold) {
          rectified = 0;
        } else {
          rectified = (rectified - threshold) / (1.0 - threshold);
        }

        // 4. Smooth Envelope (Attack/Release)
        if (rectified > currentEnvelope) {
          currentEnvelope = rectified + attackCoef * (currentEnvelope - rectified);
        } else {
          currentEnvelope = rectified + releaseCoef * (currentEnvelope - rectified);
        }

        return Math.min(Math.max(currentEnvelope, 0), 1);
      });
    }
  ),

  // ----- filters -----

  lpf: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('lp24', params.input, params.cf, params.q)
  ),

  lpf12: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('lp12', params.input, params.cf, params.q)
  ),

  lpf24: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('lp24', params.input, params.cf, params.q)
  ),

  hpf: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('hp24', params.input, params.cf, params.q)
  ),

  hpf12: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('hp12', params.input, params.cf, params.q)
  ),

  hpf24: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('hp24', params.input, params.cf, params.q)
  ),

  bpf: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('bp24', params.input, params.cf, params.q)
  ),

  bpf12: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('bp12', params.input, params.cf, params.q)
  ),

  bpf24: Module.make(
    { input: () => scalar(0), cf: () => scalar(1000), q: () => scalar(0.2) },
    params => ladder('bp24', params.input, params.cf, params.q)
  ),

  // ----- effects -----

  delay: Module.make({ input: () => scalar(0), t: () => scalar(0.25) }, params =>
    effects.delay(params.input, params.t)
  ),

  chorus: Module.make(
    {
      input: () => scalar(0),
      type: () => scalar(0.375),
      channel: () => scalar(0),
    },
    params => {
      const DELAY_BUFFER_SIZE = 2048;
      const delayBuffer = new Float32Array(DELAY_BUFFER_SIZE);
      let writeIndex = 0;
      let lfoPhase = 0;

      // Delay times in samples
      const MIN_DELAY_I_II = 0.00166 * SAMPLE_RATE; // 1.66 ms
      const MAX_DELAY_I_II = 0.00535 * SAMPLE_RATE; // 5.35 ms
      const MIN_DELAY_I_PLUS_II = 0.0033 * SAMPLE_RATE; // 3.30 ms
      const MAX_DELAY_I_PLUS_II = 0.0037 * SAMPLE_RATE; // 3.70 ms

      return Signal.new({
        nextSample: () => {
          const inputSample = params.input.value;
          const typeVal = params.type.value;
          const isRight = params.channel.value > 0.5;

          // Determine mode
          const isOff = typeVal < 0.25;
          const isChorusI = typeVal >= 0.25 && typeVal < 0.5;
          const isChorusII = typeVal >= 0.5 && typeVal < 0.75;
          const isIPlusII = typeVal >= 0.75;

          if (isOff) {
            return inputSample;
          }

          // LFO rate and delay range by mode
          let lfoRate: number;
          let minDelay: number;
          let maxDelay: number;

          if (isChorusI) {
            lfoRate = 0.513;
            minDelay = MIN_DELAY_I_II;
            maxDelay = MAX_DELAY_I_II;
          } else if (isChorusII) {
            lfoRate = 0.863;
            minDelay = MIN_DELAY_I_II;
            maxDelay = MAX_DELAY_I_II;
          } else {
            // I+II
            lfoRate = 9.75;
            minDelay = MIN_DELAY_I_PLUS_II;
            maxDelay = MAX_DELAY_I_PLUS_II;
          }

          // Triangle LFO: phase in [0,1), triangle output in [-1,1]
          const triangle = 1 - 4 * Math.abs(lfoPhase - Math.floor(lfoPhase + 0.5));
          lfoPhase += lfoRate * SAMPLE_RATE_RECIP;
          lfoPhase -= Math.floor(lfoPhase);

          // Right channel inverts the LFO (except I+II which is mono)
          const lfoValue = isRight && !isIPlusII ? -triangle : triangle;

          // Map LFO [-1,1] to [minDelay, maxDelay]
          const centerDelay = (minDelay + maxDelay) * 0.5;
          const depthSamples = (maxDelay - minDelay) * 0.5;
          const delaySamples = centerDelay + lfoValue * depthSamples;

          // Linear interpolation for fractional delay read
          const readPos = writeIndex - delaySamples + DELAY_BUFFER_SIZE;
          const readIndexFloor = Math.floor(readPos) % DELAY_BUFFER_SIZE;
          const readIndexCeil = (readIndexFloor + 1) % DELAY_BUFFER_SIZE;
          const frac = readPos - Math.floor(readPos);
          const delayedSample =
            delayBuffer[readIndexFloor] * (1 - frac) + delayBuffer[readIndexCeil] * frac;

          // No feedback -- write input only
          delayBuffer[writeIndex] = inputSample;
          writeIndex = (writeIndex + 1) % DELAY_BUFFER_SIZE;

          return Math.max(-1, Math.min(1, inputSample + delayedSample));
        },
      });
    },
    `Recreation of the Roland Juno-6 chorus effect.

Parameters:
  input   – Audio input signal (range -1 to 1).
  type    – Chorus mode, selected by ranges:
              0.00–0.25: Off (dry signal passed through)
              0.25–0.50: Chorus I   (0.513 Hz LFO, mild chorus)
              0.50–0.75: Chorus II  (0.863 Hz LFO, deeper/richer chorus)
              0.75–1.00: Chorus I+II (9.75 Hz LFO, narrow sweep, Leslie-like)
  channel – ≤0.5 produces the left channel; >0.5 produces the right channel.
            The right channel's LFO is inverted relative to the left, giving
            authentic Juno stereo width. In I+II mode both channels are identical,
            matching the original hardware.

To use in stereo: instantiate the module twice with the same input and type,
setting channel to 0 on one instance and 1 on the other. Route each to a
separate stereo output.

LFO shape is triangle throughout, matching the original BBD-based circuit.
Delay ranges are derived from measured analysis of the original hardware:
  Chorus I & II: 1.66 ms – 5.35 ms
  Chorus I+II:   3.30 ms – 3.70 ms
`
  ),

  flanger: Module.make(
    {
      input: () => scalar(0),
      manual: () => scalar(0.75),
      speed: () => scalar(0),
      width: () => scalar(0.9),
      regen: () => scalar(0.85),
    },
    params => {
      const DELAY_BUFFER_SIZE = 1024;
      const delayBuffer = new Float32Array(DELAY_BUFFER_SIZE);
      let writeIndex = 0;
      let lfoPhase = 0;

      const MIN_DELAY_SAMPLES = 0.0001 * SAMPLE_RATE; // 0.1 ms
      const MAX_DELAY_SAMPLES = 0.0128 * SAMPLE_RATE; // 12.8 ms

      return Signal.new({
        nextSample: () => {
          const inputSample = params.input.value;

          const manualVal = params.manual.value;
          const speedVal = params.speed.value;
          const widthVal = params.width.value;
          const regenVal = params.regen.value;

          // Speed: log scale, 0.1 Hz to 10 Hz
          const lfoRate = 0.1 * Math.pow(100, speedVal);

          // Feedback, capped to prevent instability
          const feedback = regenVal * 0.95;

          // LFO
          const lfoSample = Math.sin(lfoPhase * TAU);
          lfoPhase += lfoRate * SAMPLE_RATE_RECIP;
          lfoPhase -= Math.floor(lfoPhase);

          // Map lfo output [-1..1] to [0..1]
          const lfoNormalized = (lfoSample + 1) * 0.5;

          // Sweep between a floor and ceiling determined by manual and width
          const sweepMin = MIN_DELAY_SAMPLES;
          const sweepMax = MIN_DELAY_SAMPLES + widthVal * (MAX_DELAY_SAMPLES - MIN_DELAY_SAMPLES);

          // manual shifts the center of the sweep window within the full range
          const window = sweepMax - sweepMin;
          const offset = manualVal * (MAX_DELAY_SAMPLES - sweepMax);
          const delaySamples = sweepMin + offset + lfoNormalized * window;

          // Linear interpolation for fractional delay read
          const readPos = writeIndex - delaySamples + DELAY_BUFFER_SIZE;
          const readIndexFloor = Math.floor(readPos) % DELAY_BUFFER_SIZE;
          const readIndexCeil = (readIndexFloor + 1) % DELAY_BUFFER_SIZE;
          const frac = readPos - Math.floor(readPos);
          const delayedSample =
            delayBuffer[readIndexFloor] * (1 - frac) + delayBuffer[readIndexCeil] * frac;

          // Write input + feedback into delay buffer
          delayBuffer[writeIndex] = inputSample + delayedSample * feedback;
          writeIndex = (writeIndex + 1) % DELAY_BUFFER_SIZE;

          return inputSample + delayedSample;
        },
      });
    },
    `Recreation of the MXR M117R Flanger pedal.

Parameters (all 0–1, corresponding to full CCW to full CW on the original knobs):
  input  – Audio input signal (range -1 to 1). Connect your dry signal here.
  manual – Shifts the center of the delay sweep window within the full delay range.
  speed  – LFO rate, log scale from 0.1 Hz (0) to 10 Hz (1).
  width  – Width of the LFO sweep. Higher values produce a more intense, sweeping flange.
  regen  – Feedback amount (0 to 0.95 internally). Higher values increase resonance.

Mix the output with your dry signal externally to control wet/dry balance.

Sample settings from the M117R manual (knob positions read as 0–1):
  "Chained Eddie"    – manual: 0.5,  speed: 0.25, width: 0.75, regen: 0.75
  "May Gallop"       – manual: 0.25, speed: 0.5,  width: 0.5,  regen: 0.5
  "Genius of Flange" – manual: 0.75, speed: 0.1,  width: 0.9,  regen: 0.85
`
  ),

  // ----- other helpers -----

  beats: Module.make({ input: () => scalar(0.25) }, params => {
    const n = params.input;
    return Signal.new(synth => (60 / synth.sharedParams[SP_TEMPO]) * n.value);
  }),

  // TODO: change to sampleAndHold(s: Signal, clock: Signal), trigger on upward zero-crossing
  // (in the arp 2600, the noise generator is hard-wired as the input by default)

  latch: Module.make({ input: () => scalar(0), useLastValue: () => scalar(0) }, params => {
    const { input, useLastValue } = params;
    let lastValue = 0;
    return Signal.new(() => {
      if (useLastValue.value === 0) {
        lastValue = input.value;
      }
      return lastValue;
    });
  }),

  // DC blocking filter: high-pass at ~35Hz to remove DC while preserving audible content
  // Uses a one-pole high-pass: y[n] = x[n] - x[n-1] + α * y[n-1]
  dcBlock: Module.make({ input: () => scalar(0) }, params => {
    const { input } = params;
    // α = 0.995 gives ~35Hz cutoff at 48kHz
    const alpha = 0.995;
    let prevX = 0;
    let prevY = 0;
    return Signal.new(() => {
      const x = input.value;
      const y = x - prevX + alpha * prevY;
      prevX = x;
      prevY = y;
      return y;
    });
  }),

  pitchShift: Module.make(
    { input: () => scalar(0), amount: () => scalar(0) },
    (params) => {
      const inputSig = params.input;
      const amountSig = params.amount;
  
      // ---- Phase vocoder configuration ----
      const fftFrameSize = 1024;       // analysis/synthesis window size (samples)
      const osamp = 4;                 // oversampling factor (75% overlap)
      const stepSize = fftFrameSize / osamp;
      const fftFrameSize2 = fftFrameSize / 2;
      const freqPerBin = SAMPLE_RATE / fftFrameSize;
      const expct = TAU * stepSize / fftFrameSize;
      const inFifoLatency = fftFrameSize - stepSize;
  
      // ---- Preallocated state (no allocation in the audio-rate path) ----
      const gInFIFO = new Float64Array(fftFrameSize);
      const gOutFIFO = new Float64Array(fftFrameSize);
      const gFFTworksp = new Float64Array(2 * fftFrameSize);
      const gLastPhase = new Float64Array(fftFrameSize2 + 1);
      const gSumPhase = new Float64Array(fftFrameSize2 + 1);
      const gOutputAccum = new Float64Array(2 * fftFrameSize);
      const gAnaFreq = new Float64Array(fftFrameSize2 + 1);
      const gAnaMagn = new Float64Array(fftFrameSize2 + 1);
      const gSynFreq = new Float64Array(fftFrameSize2 + 1);
      const gSynMagn = new Float64Array(fftFrameSize2 + 1);
  
      let gRover = inFifoLatency;
  
      // In-place FFT/IFFT (Cooley-Tukey, interleaved re/im layout).
      // sign = -1 for forward transform, +1 for inverse.
      const smbFft = (buf: Float64Array, frameSize: number, sign: number) => {
        let i: number, bitm: number, j: number, le: number, le2: number, k: number;
        let wr: number, wi: number, arg: number, temp: number;
        let tr: number, ti: number, ur: number, ui: number;
        let p1r: number, p1i: number, p2r: number, p2i: number;
  
        for (i = 2; i < 2 * frameSize - 2; i += 2) {
          for (bitm = 2, j = 0; bitm < 2 * frameSize; bitm <<= 1) {
            if ((i & bitm) !== 0) j++;
            j <<= 1;
          }
          if (i < j) {
            temp = buf[i]; buf[i] = buf[j]; buf[j] = temp;
            temp = buf[i + 1]; buf[i + 1] = buf[j + 1]; buf[j + 1] = temp;
          }
        }
  
        const kmax = Math.floor(Math.log(frameSize) / Math.LN2 + 0.5);
        for (k = 0, le = 2; k < kmax; k++) {
          le <<= 1;
          le2 = le >> 1;
          ur = 1.0;
          ui = 0.0;
          arg = Math.PI / (le2 >> 1);
          wr = Math.cos(arg);
          wi = sign * Math.sin(arg);
          for (j = 0; j < le2; j += 2) {
            p1r = j; p1i = p1r + 1;
            p2r = p1r + le2; p2i = p2r + 1;
            for (i = j; i < 2 * frameSize; i += le) {
              tr = buf[p2r] * ur - buf[p2i] * ui;
              ti = buf[p2r] * ui + buf[p2i] * ur;
              buf[p2r] = buf[p1r] - tr;
              buf[p2i] = buf[p1i] - ti;
              buf[p1r] += tr;
              buf[p1i] += ti;
              p1r += le; p1i += le;
              p2r += le; p2i += le;
            }
            tr = ur * wr - ui * wi;
            ui = ur * wi + ui * wr;
            ur = tr;
          }
        }
      };
  
      // Hann analysis/synthesis window
      const winAt = (k: number) => -0.5 * Math.cos((TAU * k) / fftFrameSize) + 0.5;
  
      return Signal.new({
        nextSample: () => {
          const indata = inputSig.value;
  
          gInFIFO[gRover] = indata;
          const outSample = gOutFIFO[gRover - inFifoLatency];
          gRover++;
  
          if (gRover >= fftFrameSize) {
            gRover = inFifoLatency;
  
            const semitones = amountSig.value;
            const pitchShift = Math.pow(2, semitones / 12);
  
            // ---- windowing + forward FFT ----
            for (let k = 0; k < fftFrameSize; k++) {
              const w = winAt(k);
              gFFTworksp[2 * k] = gInFIFO[k] * w;
              gFFTworksp[2 * k + 1] = 0;
            }
            smbFft(gFFTworksp, fftFrameSize, -1);
  
            // ---- analysis: magnitude + true bin frequency via phase tracking ----
            for (let k = 0; k <= fftFrameSize2; k++) {
              const real = gFFTworksp[2 * k];
              const imag = gFFTworksp[2 * k + 1];
              const magn = 2 * Math.sqrt(real * real + imag * imag);
              const phase = Math.atan2(imag, real);
  
              let tmp = phase - gLastPhase[k];
              gLastPhase[k] = phase;
  
              tmp -= k * expct;
  
              let qpd = Math.trunc(tmp / Math.PI);
              if (qpd >= 0) qpd += qpd & 1;
              else qpd -= qpd & 1;
              tmp -= Math.PI * qpd;
  
              tmp = (osamp * tmp) / TAU;
              tmp = k * freqPerBin + tmp * freqPerBin;
  
              gAnaMagn[k] = magn;
              gAnaFreq[k] = tmp;
            }
  
            // ---- pitch shift: remap bins in the frequency domain ----
            gSynMagn.fill(0);
            gSynFreq.fill(0);
            for (let k = 0; k <= fftFrameSize2; k++) {
              const index = Math.floor(k * pitchShift);
              if (index <= fftFrameSize2) {
                gSynMagn[index] += gAnaMagn[k];
                gSynFreq[index] = gAnaFreq[k] * pitchShift;
              }
            }
  
            // ---- synthesis: rebuild phase from true frequency, hop size unchanged ----
            for (let k = 0; k <= fftFrameSize2; k++) {
              const magn = gSynMagn[k];
              let tmp = gSynFreq[k];
  
              tmp -= k * freqPerBin;
              tmp /= freqPerBin;
              tmp = (TAU * tmp) / osamp;
              tmp += k * expct;
  
              gSumPhase[k] += tmp;
              const phase = gSumPhase[k];
  
              gFFTworksp[2 * k] = magn * Math.cos(phase);
              gFFTworksp[2 * k + 1] = magn * Math.sin(phase);
            }
            for (let k = fftFrameSize + 2; k < 2 * fftFrameSize; k++) gFFTworksp[k] = 0;
  
            smbFft(gFFTworksp, fftFrameSize, 1);
  
            for (let k = 0; k < fftFrameSize; k++) {
              const w = winAt(k);
              gOutputAccum[k] += (2 * w * gFFTworksp[2 * k]) / (fftFrameSize2 * osamp);
            }
            for (let k = 0; k < stepSize; k++) gOutFIFO[k] = gOutputAccum[k];
  
            gOutputAccum.copyWithin(0, stepSize, stepSize + fftFrameSize);
            gInFIFO.copyWithin(0, stepSize, fftFrameSize);
          }
  
          return outSample;
        },
      });
    },
    'A real-time phase-vocoder pitch shifter, built on the same core technique the Rubber ' +
    'Band real-time pitch shifter uses: the input is analyzed in overlapping FFT frames, and ' +
    'each bin\'s phase is tracked across frames to estimate its true instantaneous frequency ' +
    '(not just its bin-center frequency). Those true frequencies are remapped in the ' +
    'frequency domain by the pitch ratio and used to rebuild a consistent synthesis phase, ' +
    'then resynthesized with the SAME hop size as the analysis. Because the hop size never ' +
    'changes, the output stays locked to the input\'s timing -- this is what avoids the ' +
    'classic "Darth Vader / chipmunk" problem you get from naive resampling-based pitch ' +
    'shifters, where speeding up or slowing down playback changes pitch and duration ' +
    'together. `amount` is the shift in semitones (12 = up an octave, -12 = down an octave, ' +
    '0 = no shift; fractional values work too, and are nice for subtle detune/chorus ' +
    'effects). The algorithm has about 21ms of inherent latency (one analysis frame) and ' +
    'sounds best for shifts within roughly +/-1 octave -- push it further and, like any ' +
    'phase-vocoder shifter, transients will start to smear a bit.'
  ),

  pitchf: Module.make(
    {
      input: () => scalar(0),
      confidence: () => scalar(0.9),
      silenceThreshold: () => scalar(0.006),
    },
    (params) => {
      const inputSig = params.input;
      const confidenceSig = params.confidence;
      const silenceThresholdSig = params.silenceThreshold;
  
      // Lowest trackable frequency determines how much history we need.
      // This is a hard physical trade-off: lower minFreq = better bass
      // tracking but longer inherent latency at note onset, since you need
      // at least ~1-2 periods of the fundamental to buffer before it can
      // be detected at all.
      const minFreq = 70; // Hz
      const maxLag = Math.ceil(SAMPLE_RATE / minFreq);
      const windowSize = maxLag * 2;
      // 75% overlap: fast 7ms updates for responsiveness.
      const hopSize = Math.floor(windowSize / 4);
  
      // Circular input buffer.
      const buffer = new Float32Array(windowSize);
      let writeIndex = 0;
      let filled = false;
      let samplesSinceHop = 0;
  
      // Scratch buffers reused every hop (no per-sample allocation).
      const scratch = new Float32Array(windowSize);
      const nsdf = new Float32Array(maxLag + 1);
      const maxPositionsTau: number[] = [];
      const maxPositionsVal: number[] = [];
      let sumOfSquares = 0;
  
      // Raw per-hop estimate.
      let rawFreq = 0;
      let rawClarity = 0;
  
      // Accepted ("stable") output, plus a single-hop holding area used only
      // to confirm suspicious large jumps (e.g. octave errors) before either
      // accepting or discarding them.
      let stableFreq = 0;
      let stableClarity = 0;
      let pendingFreq = 0;
      let pendingCount = 0;
  
      function computeNSDF() {
        // Linearize the circular buffer into temporal order.
        for (let j = 0; j < windowSize; j++) {
          scratch[j] = buffer[(writeIndex + j) % windowSize];
        }
        // Normalized square difference function (McLeod & Wyvill).
        for (let tau = 0; tau <= maxLag; tau++) {
          let acf = 0;
          let m = 0;
          const n = windowSize - tau;
          for (let j = 0; j < n; j++) {
            const a = scratch[j];
            const b = scratch[j + tau];
            acf += a * b;
            m += a * a + b * b;
          }
          if (tau === 0) {
            // m(0) = 2 * sum(x^2) over the window; reuse it to get RMS
            // for free, without an extra pass over the buffer.
            sumOfSquares = m * 0.5;
          }
          nsdf[tau] = m > 0 ? (2 * acf) / m : 0;
        }
      }
  
      function pickPitch(): void {
        maxPositionsTau.length = 0;
        maxPositionsVal.length = 0;
  
        // Find "key maxima": local peaks within each positive lobe of the NSDF.
        let tau = 1;
        while (tau < maxLag) {
          while (tau < maxLag && !(nsdf[tau - 1] < 0 && nsdf[tau] >= 0)) tau++;
          if (tau >= maxLag) break;
          let maxVal = -Infinity;
          let maxTau = tau;
          while (tau < maxLag && nsdf[tau] >= 0) {
            if (nsdf[tau] > maxVal) {
              maxVal = nsdf[tau];
              maxTau = tau;
            }
            tau++;
          }
          maxPositionsTau.push(maxTau);
          maxPositionsVal.push(maxVal);
        }
  
        if (maxPositionsTau.length === 0) {
          rawFreq = 0;
          rawClarity = 0;
          return;
        }
  
        // Highest key maximum sets the reference level.
        let highest = 0;
        for (let i = 0; i < maxPositionsVal.length; i++) {
          if (maxPositionsVal[i] > highest) highest = maxPositionsVal[i];
        }
  
        // Pick the first (smallest-lag / highest-frequency) peak that's close
        // enough to the strongest peak. This is what makes MPM resistant to
        // octave errors compared to plain YIN.
        const k = 0.9;
        let chosenIdx = 0;
        for (let i = 0; i < maxPositionsVal.length; i++) {
          if (maxPositionsVal[i] >= k * highest) {
            chosenIdx = i;
            break;
          }
        }
  
        const chosenTau = maxPositionsTau[chosenIdx];
        let refinedTau = chosenTau;
        let refinedVal = maxPositionsVal[chosenIdx];
  
        // Parabolic interpolation around the chosen peak for sub-sample lag accuracy.
        if (chosenTau > 0 && chosenTau < maxLag) {
          const s0 = nsdf[chosenTau - 1];
          const s1 = nsdf[chosenTau];
          const s2 = nsdf[chosenTau + 1];
          const denom = 2 * (2 * s1 - s2 - s0);
          if (denom !== 0) {
            const delta = (s2 - s0) / denom;
            refinedTau = chosenTau + delta;
            refinedVal = s1 - 0.25 * (s0 - s2) * delta;
          }
        }
  
        if (refinedTau <= 0) {
          rawFreq = 0;
          rawClarity = 0;
          return;
        }
  
        rawFreq = SAMPLE_RATE / refinedTau;
        rawClarity = refinedVal;
      }
  
      function resetTracking() {
        stableFreq = 0;
        stableClarity = 0;
        pendingFreq = 0;
        pendingCount = 0;
      }
  
      // Decide what to output for this hop, given a fresh raw estimate.
      // Three tiers of response, by how large the change from the last
      // accepted value is:
      //   - tiny (<3%): almost certainly analysis jitter on a sustained
      //     note -> smoothed heavily in log-frequency space to kill zipper
      //     noise without a big latency cost.
      //   - moderate (3%-40%): a real note change, bend, or vibrato ->
      //     passed through immediately with zero added latency.
      //   - large (>40%): likely an octave error -> held for one hop and
      //     only accepted if the next hop confirms it.
      const microThreshold = 1.03;
      const jumpThreshold = 1.4;
      const jitterSmoothing = 0.6; // fraction of old (log) value retained per hop
  
      function updateStable() {
        if (stableFreq === 0 || rawFreq === 0) {
          stableFreq = rawFreq;
          stableClarity = rawClarity;
          pendingCount = 0;
          return;
        }
  
        const ratio = rawFreq / stableFreq;
        const ratioAbs = ratio >= 1 ? ratio : 1 / ratio;
  
        if (ratioAbs >= jumpThreshold) {
          // Suspicious jump: only accept if the previous hop already saw
          // roughly the same new value (i.e. it's consistent, not a blip).
          if (
            pendingCount > 0 &&
            Math.abs(rawFreq - pendingFreq) / pendingFreq < 0.05
          ) {
            stableFreq = rawFreq;
            stableClarity = rawClarity;
            pendingCount = 0;
          } else {
            pendingFreq = rawFreq;
            pendingCount = 1;
          }
        } else if (ratioAbs >= microThreshold) {
          // Real, deliberate pitch movement - pass through immediately.
          stableFreq = rawFreq;
          stableClarity = rawClarity;
          pendingCount = 0;
        } else {
          // Tiny fluctuation around a sustained pitch - smooth it out.
          const logOld = Math.log2(stableFreq);
          const logNew = Math.log2(rawFreq);
          const logSmoothed = logOld + (1 - jitterSmoothing) * (logNew - logOld);
          stableFreq = Math.pow(2, logSmoothed);
          stableClarity =
            stableClarity + (1 - jitterSmoothing) * (rawClarity - stableClarity);
          pendingCount = 0;
        }
      }
  
      return Signal.new({
        nextSample: () => {
          const sample = inputSig.value;
          buffer[writeIndex] = sample;
          writeIndex = (writeIndex + 1) % windowSize;
          samplesSinceHop++;
  
          if (!filled && writeIndex === 0) filled = true;
  
          if (filled && samplesSinceHop >= hopSize) {
            samplesSinceHop = 0;
            computeNSDF();
  
            const rms = Math.sqrt(sumOfSquares / windowSize);
            if (rms < silenceThresholdSig.value) {
              rawFreq = 0;
              rawClarity = 0;
              resetTracking();
            } else {
              pickPitch();
              updateStable();
            }
          }
  
          const threshold = confidenceSig.value;
          return stableClarity >= threshold ? stableFreq : 0;
        },
      });
    },
    `A real-time monophonic pitch tracker using the McLeod Pitch Method (MPM), a modern ` +
    `refinement of autocorrelation-based pitch detection (the successor to the classic YIN ` +
    `algorithm). Analyzes 'input' in overlapping ~28ms windows, updated every ~7ms, refined to ` +
    `sub-sample accuracy via parabolic interpolation.\n\n` +
    `'confidence' (0 to 1) sets how strict the pitch clarity requirement is before a value is ` +
    `reported; below it, the output is 0.\n\n` +
    `'silenceThreshold' (0 to 1) is an RMS energy gate that skips detection entirely on ` +
    `low-energy input, preventing spurious pitch readings during silence or decay tails. Default ` +
    `0.006 is tuned to pass quiet singing/playing while still gating true silence.\n\n` +
    `Internally, small hop-to-hop fluctuations (analysis jitter on a sustained note) are smoothed ` +
    `to avoid a noisy/glitchy output; real pitch changes (note changes, bends, vibrato) pass ` +
    `through immediately with no added latency; large jumps (typically octave errors) are held ` +
    `for one ~7ms hop and only accepted if confirmed by the next estimate.\n\n` +
    `Tracks fundamentals down to about 70 Hz. Detecting low notes inherently takes longer than ` +
    `high notes (roughly 1-2 periods of the fundamental must be buffered before it can be ` +
    `identified), so expect a bit more latency right at the onset of low notes - this is a ` +
    `physical limit of pitch detection, not a bug. Works best on genuinely monophonic, reasonably ` +
    `clean input (a single voice or instrument).`
  ),

  envf: Module.make(
    {
      input: () => scalar(0),
      attack: () => scalar(0.1),
      release: () => scalar(0.4),
    },
    (params) => {
      const inputSig = params.input;
      const attackSig = params.attack;
      const releaseSig = params.release;
  
      // Map a 0-1 knob to a time constant in seconds, exponentially, so the
      // low end of the knob gives fine control over fast times.
      const attackMin = 0.0005; // 0.5ms - near-instant attack
      const attackMax = 0.5; // 500ms - slow swell
      const releaseMin = 0.005; // 5ms - fast release
      const releaseMax = 3.0; // 3s - long, smooth decay
  
      function timeFromKnob(knob: number, min: number, max: number): number {
        const t = Math.max(0, Math.min(1, knob));
        return min * Math.pow(max / min, t);
      }
  
      function coeffFromTime(seconds: number): number {
        // Standard one-pole smoothing coefficient for a given time constant.
        return Math.exp(-1 / (seconds * SAMPLE_RATE));
      }
  
      let envSquared = 0;
  
      return Signal.new({
        nextSample: () => {
          const sample = inputSig.value;
          const squared = sample * sample;
  
          // Recompute coefficients each sample so attack/release can be
          // modulated live; this is cheap (a couple of exp() calls) relative
          // to typical audio-rate work.
          const attackTime = timeFromKnob(attackSig.value, attackMin, attackMax);
          const releaseTime = timeFromKnob(releaseSig.value, releaseMin, releaseMax);
  
          const coeff =
            squared > envSquared
              ? coeffFromTime(attackTime)
              : coeffFromTime(releaseTime);
  
          envSquared = coeff * envSquared + (1 - coeff) * squared;
          if (envSquared < 0) envSquared = 0; // guard against float underflow
  
          return Math.sqrt(envSquared);
        },
      });
    },
    `An RMS-style envelope follower ("volume follower") with independent attack and release ` +
    `times, ideal for driving the amplitude of a synthesized voice from a natural input signal ` +
    `like singing or an instrument. Unlike a plain windowed RMS calculation, this works sample-` +
    `by-sample with no block latency, and its asymmetric attack/release response lets note onsets ` +
    `come through quickly while decays stay smooth rather than choppy.\n\n` +
    `'attack' (0 to 1) controls how fast the output rises to match increasing input energy - low ` +
    `values (near 0) snap almost instantly to note onsets for punchy, responsive tracking; higher ` +
    `values create a slower swell.\n\n` +
    `'release' (0 to 1) controls how fast the output falls as input energy decreases - low values ` +
    `release quickly (can sound choppy on sustained/vibrato-heavy material); higher values glide ` +
    `smoothly through natural decays and breaths, which is usually what you want for expressive, ` +
    `natural-sounding volume following. A good starting point is a fast-ish attack (0.05-0.15) ` +
    `paired with a moderate-to-slow release (0.3-0.5).\n\n` +
    `Output is in the range 0 to 1, representing signal amplitude. To make an expressive patch, ` +
    `multiply a synthesized oscillator (e.g. driven by a pitch tracker's frequency output) by this ` +
    `module's output - the synthesized voice will then swell and fade with your original ` +
    `performance's dynamics.`
  ),

  semitones: Module.make({ input: () => scalar(0) }, params =>
    Signal.new(() => Math.pow(2, params.input.value / 12))
  ),
};

// https://mitxela.com/projects/bleps_via_state_machine
function polyBlep(t: number, dt: number) {
  // 0 <= t < 1
  if (t < dt) {
    t /= dt;
    // 2 * (t - t^2/2 - 0.5)
    return t + t - t * t - 1;
  }

  // -1 < t < 0
  if (t > 1 - dt) {
    t = (t - 1) / dt;
    // 2 * (t^2/2 + t + 0.5)
    return t * t + t + t + 1;
  }

  // 0 otherwise
  return 0;
}

(globalThis as any).msynthLib = msynthLib;
